          parser: '>app/1.0.0>parser/1.0.0>',
          plugin: '>app/1.0.0>plugin/1.0.0>',
          typescript: '>app/1.0.0>typescript/1.0.0>',
        },
        installable: true,
        resolvedPackage: app,
        depth: 0,
      }],
      ['>app/1.0.0>parser/1.0.0>', { children: {}, installable: true, resolvedPackage: parser, depth: 1 }],
      ['>app/1.0.0>plugin/1.0.0>', { children: {}, installable: true, resolvedPackage: plugin, depth: 1 }],
      ['>app/1.0.0>typescript/1.0.0>', { children: {}, installable: true, resolvedPackage: ts1, depth: 1 }],
    ]),
    virtualStoreDir: '',
    virtualStoreDirMaxLength: 120,
    lockfileDir: '',
    peersSuffixMaxLength: 1000,
    workspaceProjectIds: new Set(),
  })
  console.log('GRAPH KEYS:')
  console.log(Object.keys(dependenciesGraph).sort().join('\n'))
}

run().catch((e) => { console.error(e); process.exit(1) })
