// resolved against `childScope`. When any shared peer differs, the local
// instance must be used so diamond peers stay mutually consistent.
function sharedPeersResolveConsistently<T extends PartialResolvedPackage> (
  ctx: {
    dependenciesTree: DependenciesTree<T>
    parentPkgsOfNode: ParentPkgsOfNode
  },
  ancestorPkg: ParentRef,
  localPkg: ParentRef,
  childScope: ParentRefs
): boolean {
  if (localPkg.nodeId == null || ancestorPkg.nodeId == null) return true
  const peerDependencies = ctx.dependenciesTree.get(localPkg.nodeId)?.resolvedPackage.peerDependencies
  if (peerDependencies == null) return true
  const peerNames = Object.keys(peerDependencies)
  if (peerNames.length === 0) return true
  const ancestorScope = ctx.parentPkgsOfNode.get(ancestorPkg.nodeId)
  if (ancestorScope == null) return true
  for (const peerName of peerNames) {
    const ancestorPeer = ancestorScope[peerName]
    const localPeer = childScope[peerName]
    if ((ancestorPeer == null) !== (localPeer == null)) return false
    if (ancestorPeer == null || localPeer == null) continue
    if (peerRefKey(ctx.dependenciesTree, localPeer) !== parentPkgInfoKey(ancestorPeer)) {
      return false
    }
  }
  return true
}

function peerRefKey<T extends PartialResolvedPackage> (
  dependenciesTree: DependenciesTree<T>,
  ref: ParentRef
): string | undefined {
  if (ref.nodeId != null && !(typeof ref.nodeId === 'string' && ref.nodeId.startsWith('link:'))) {
    const pkgId = dependenciesTree.get(ref.nodeId)?.resolvedPackage.pkgIdWithPatchHash
    if (pkgId != null) return `id:${pkgId}`
  }
  return ref.version != null ? `v:${ref.version}` : undefined
}

function parentPkgInfoKey (info: ParentPkgInfo): string | undefined {
  if (info.pkgIdWithPatchHash != null) return `id:${info.pkgIdWithPatchHash}`
  return info.version != null ? `v:${info.version}` : undefined
}

